import Foundation
import Testing
@testable import ScriptureTextTestSupport

/// The test-support zlib reader, against streams made by zlib itself (Python's `zlib.compress`) for each block
/// type: stored, fixed Huffman and dynamic Huffman. The real proof is every module in the repo reading correctly.
struct InflateTests {

    private let repeated: [UInt8] = [0x78, 0xda, 0xf3, 0xcc, 0x53, 0x28, 0xc9, 0x48, 0x55, 0x48, 0x4a, 0x4d, 0xcf, 0xcc, 0xcb, 0xcb, 0xcc, 0x4b, 0x57, 0x70, 0xcf, 0x4f, 0x51, 0x48, 0x2e, 0x4a, 0x4d, 0x2c, 0x49, 0x4d, 0x01, 0xcb, 0x64, 0xa4, 0x26, 0x96, 0xa5, 0xe6, 0x29, 0x24, 0xe6, 0x41, 0xb8, 0xa9, 0x89, 0x45, 0x25, 0x19, 0x7a, 0x0a, 0x9e, 0x74, 0xd5, 0x06, 0x00, 0xd6, 0x5c, 0x39, 0xdc]
    private let tiny: [UInt8] = [0x78, 0x01, 0x4b, 0x4c, 0x4a, 0x06, 0x00, 0x02, 0x4d, 0x01, 0x27]
    private let stored: [UInt8] = [0x78, 0x01, 0x01, 0x0d, 0x00, 0xf2, 0xff, 0x73, 0x74, 0x6f, 0x72, 0x65, 0x64, 0x20, 0x62, 0x6c, 0x6f, 0x63, 0x6b, 0x21, 0x24, 0x5e, 0x04, 0xde]
    private let dynamic: [UInt8] = [0x78, 0xda, 0xed, 0x8e, 0x41, 0x0a, 0x02, 0x31, 0x0c, 0x45, 0xaf, 0xf2, 0x4f, 0x30, 0x07, 0xd0, 0xad, 0x0b, 0x05, 0x41, 0xd0, 0xb9, 0x40, 0xb4, 0x19, 0x5b, 0xcc, 0x34, 0x43, 0x53, 0x29, 0xbd, 0xbd, 0x2d, 0xcc, 0x15, 0xdc, 0x75, 0x97, 0x84, 0xff, 0xdf, 0xcb, 0xec, 0x19, 0xd7, 0xdb, 0xfd, 0x84, 0x60, 0x58, 0x2b, 0xcc, 0xf3, 0xe6, 0x39, 0xb9, 0x23, 0x2e, 0x6d, 0x26, 0x11, 0x44, 0xcd, 0x28, 0x14, 0xf3, 0x84, 0x33, 0x63, 0xa5, 0x0f, 0x67, 0x8f, 0x95, 0x91, 0x15, 0x12, 0x18, 0x4e, 0x4b, 0x44, 0x88, 0x78, 0x27, 0xe6, 0x88, 0x8d, 0x2c, 0x7f, 0x13, 0xdb, 0x01, 0x8d, 0x2a, 0x4c, 0x6e, 0x0f, 0x3f, 0xd9, 0x82, 0x6b, 0x9d, 0x76, 0xb5, 0x1c, 0x1a, 0xb4, 0x50, 0xe6, 0x64, 0x13, 0xe6, 0x61, 0x1f, 0xf6, 0x61, 0x1f, 0xf6, 0x61, 0xff, 0xb3, 0xfd, 0xd1, 0xd2, 0x52, 0xf1, 0x56, 0x75, 0x91, 0xcd, 0x40, 0xd1, 0xb5, 0x7c, 0x7a, 0xd5, 0x5d, 0xbe, 0xa8, 0x88, 0x96, 0x8e, 0xe8, 0x5b, 0xef, 0x3b, 0xaa, 0x06, 0x5d, 0xfa, 0xaf, 0x12, 0x16, 0xc6, 0x0f, 0x42, 0x13, 0x25, 0x9f]
    private let dynamicText = "The LORD is my shepherd; I shall not want. He maketh me to lie down in green pastures: he leadeth me beside the still waters. The LORD is my shepherd; I shall not want. He maketh me to lie down in green pastures: he leadeth me beside the still waters. The LORD is my shepherd; I shall not want. He maketh me to lie down in green pastures: he leadeth me beside the still waters. The LORD is my shepherd; I shall not want. He maketh me to lie down in green pastures: he leadeth me beside the still waters. The LORD is my shepherd; I shall not want. He maketh me to lie down in green pastures: he leadeth me beside the still waters. The LORD is my shepherd; I shall not want. He maketh me to lie down in green pastures: he leadeth me beside the still waters. The LORD is my shepherd; I shall not want. He maketh me to lie down in green pastures: he leadeth me beside the still waters. The LORD is my shepherd; I shall not want. He maketh me to lie down in green pastures: he leadeth me beside the still waters. The LORD is my shepherd; I shall not want. He maketh me to lie down in green pastures: he leadeth me beside the still waters. The LORD is my shepherd; I shall not want. He maketh me to lie down in green pastures: he leadeth me beside the still waters. The LORD is my shepherd; I shall not want. He maketh me to lie down in green pastures: he leadeth me beside the still waters. The LORD is my shepherd; I shall not want. He maketh me to lie down in green pastures: he leadeth me beside the still waters. Surely goodness and mercy shall follow me all the days of my life "

    @Test func aRepeatedStringUsesBackReferences() throws {
        let out = try Inflate.zlib(Data(repeated))
        #expect(String(decoding: out, as: UTF8.self) == String(repeating: "In the beginning God created the heaven and the earth. ", count: 3))
    }

    @Test func aFixedHuffmanBlock() throws {
        #expect(String(decoding: try Inflate.zlib(Data(tiny)), as: UTF8.self) == "abc")
    }

    @Test func aStoredBlock() throws {
        #expect(String(decoding: try Inflate.zlib(Data(stored)), as: UTF8.self) == "stored block!")
    }

    @Test func aDynamicHuffmanBlock() throws {
        // Byte 2 of the stream holds the block header: bits 1-2 are the block type, 2 = dynamic.
        #expect((dynamic[2] >> 1) & 3 == 2)
        #expect(String(decoding: try Inflate.zlib(Data(dynamic)), as: UTF8.self) == dynamicText)
    }

    @Test func truncatedAndCorruptDataThrowsInsteadOfCrashing() {
        #expect(throws: Inflate.Failure.self) { try Inflate.zlib(Data(dynamic.prefix(40))) }
        #expect(throws: Inflate.Failure.self) { try Inflate.zlib(Data([0x78])) }
        #expect(throws: Inflate.Failure.self) { try Inflate.zlib(Data([0x00, 0x00, 0x07])) }
    }
}
